    /**
     * Method to retrieve the Clinician via ClinicianFetchOneSummary
     * @param 	summary ClinicianFetchOneSummary 
     * @return 	ClinicianFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Clinician getClinician( ClinicianFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ClinicianFetchOneSummary arg cannot be null" );
    	
    	Clinician entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Clinician
        	// --------------------------------------
        	CompletableFuture<Clinician> futureEntity = queryGateway.query(new FindClinicianQuery( new LoadClinicianFilter( summary.getClinicianId() ) ), ResponseTypes.instanceOf(Clinician.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Clinician with id " + summary.getClinicianId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


